import childProcess from 'node:child_process';
import http from 'node:http';
import https from 'node:https';
import net from 'node:net';
import { syncBuiltinESMExports } from 'node:module';
import assert from 'node:assert/strict';
import { readFile } from 'node:fs/promises';
let effects = 0;
const forbidden = () => { effects++; throw new Error('Authoring attempted a side effect'); };
for (const method of ['spawn', 'fork', 'exec', 'execFile']) childProcess[method] = forbidden;
http.request = http.get = https.request = https.get = net.connect = net.createConnection = forbidden;
globalThis.fetch = forbidden;
syncBuiltinESMExports();
const { composeBlueprint, createTemplate, listTemplates } = await import('../../packages/core/index.mjs');
const fixtures = JSON.parse(await readFile(new URL('./compose-inputs.json', import.meta.url))).fixtures;
const inputs = fixtures.slice(0, 2).map(f => ({ schemaVersion: 'qa.composition/v1', assets: f.assets.map(({ id, format, source, sha256 }) => ({ id, format, source, sha256 })), instances: f.instances.map(({ id, assetId }) => ({ id, assetId })), links: f.links }));
const results = await Promise.all(inputs.map(input => Promise.resolve().then(() => composeBlueprint(input))));
assert.notEqual(results[0].blueprintSnapshotHash, results[1].blueprintSnapshotHash);
const t = listTemplates().templates[0];
createTemplate({ templateId: t.id, version: t.version, sha256: t.sha256, bindings: { id: 'empty', target: results[0].blueprint.target } });
assert.equal(effects, 0);
console.log(JSON.stringify({ effects, independentRequests: results.length, imports: 'public root', passed: true }));
